class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        n = len(arr)
        P = [0] * (n + 1)
        for k in range(n):
            P[k + 1] = P[k] + arr[k]
        total = P[n]
        for i in range(n - 2):
            s1 = P[i + 1]
            for j in range(i + 2, n):
                if s1 == P[j] - s1 == total - P[j]:
                    return True
        return False

