class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        total = sum(arr)
        if total % 3:
            return False
        target = total // 3
        run, parts = 0, 0
        for x in arr:
            run += x
            if run == target:
                run = 0
                parts += 1
        return parts >= 3

