class Solution {
public:
    bool canThreePartsEqualSum(vector<int>& arr) {
        long long total = accumulate(arr.begin(), arr.end(), 0LL);
        if (total % 3) return false;
        long long target = total / 3, run = 0;
        int parts = 0;
        for (int x : arr) {
            run += x;
            if (run == target) { run = 0; parts++; }
        }
        return parts >= 3;
    }
};

