        long total = 0;
        for (int x : arr) total += x;
        if (total % 3 != 0) return false;
        long target = total / 3, run = 0;
        int parts = 0;
        for (int x : arr) {
            run += x;
            if (run == target) { run = 0; parts++; }
        }
        return parts >= 3;
    }
}

